using UnityEditor;using UnityEngine;using UnityEngine.UI;using TMPro;using System.Linq;using VisualAlgo.Managers.UI;
public static class InspectHullEntry{public static object Run(){return new {scenes=EditorBuildSettings.scenes.Select(x=>x.path).ToArray(),dirty=UnityEditor.SceneManagement.EditorSceneManager.GetActiveScene().isDirty,buttons=Object.FindObjectsByType<Button>(FindObjectsInactive.Include,FindObjectsSortMode.None).Where(x=>x.name.StartsWith("Btn_")).Select(x=>new{name=x.name,rect=((RectTransform)x.transform).anchoredPosition.ToString(),size=((RectTransform)x.transform).sizeDelta.ToString(),components=x.GetComponents<Component>().Select(c=>c.GetType().Name).ToArray(),title=x.GetComponentInChildren<TMP_Text>()?.text}).ToArray(),pause=Object.FindObjectsByType<PauseMenuController>(FindObjectsInactive.Include,FindObjectsSortMode.None).Select(x=>EditorJsonUtility.ToJson(x)).ToArray(),canvas=Object.FindObjectsByType<Canvas>(FindObjectsSortMode.None).Select(x=>new{name=x.name,mode=x.renderMode.ToString(),scale=x.GetComponent<CanvasScaler>()?.referenceResolution.ToString()}).ToArray()};}}
